   240→      const response = await apiFetch('/api/report/export-pdf', {
   241→        method: 'POST',
   242→        headers: { 'Content-Type': 'application/json' },
   243→        body: JSON.stringify({
   244→          title: activeReport.title,
   245→          summary: activeReport.summary,
   246→          createdAt: activeReport.createdAt,
   247→          templateType: activeReport.templateType,
   248→          kpiList: activeReport.kpiList || [],
   249→          insights: activeReport.insights || [],
   250→          charts,
   251→          orientation: pdfOrientation,
   252→        }),
   253→      });
