   255→        const err = await response.json().catch(() => null);
   256→        throw new Error(err?.error || `导出失败（${response.status}）`);
   257→      }
   258→      const blob = await response.blob();
   259→      const url = URL.createObjectURL(blob);
   260→      const a = document.createElement('a');
   261→      a.href = url;
   262→      a.download = `${activeReport.title.replace(/[\\/:*?"<>|\s]+/g, '_')}_分析简报_${activeReport.createdAt}.pdf`;
   263→      document.body.appendChild(a);
   264→      a.click();
   265→      a.remove();
   266→      URL.revokeObjectURL(url);
   267→      setPdfExportSuccess(true);
   268→      setTimeout(() => setPdfExportSuccess(false), 2000);
   269→    } catch (err: any) {
   270→      console.error('PDF Export Error:', err);
   271→      alert(`PDF 导出失败：${err?.message || '未知错误'}`);
   272→    } finally {
   273→      setIsExportingPDF(false);
   274→    }
   275→  };
