   287→      }`}
   288→    >
   289→      {/* Report Header */}
   290→      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-800 pb-5">
   291→        <div className="space-y-1">
   292→          <div className="flex items-center space-x-2 flex-wrap gap-y-1">
   293→            <span className="px-2.5 py-0.5 rounded-full text-xs font-semibold bg-indigo-500/20 text-indigo-300 border border-indigo-500/30">
   294→              AI 高管决策简报
   295→            </span>
   296→            <span className="text-xs text-slate-400 flex items-center space-x-1">
   297→              <Calendar className="w-3.5 h-3.5" />
   298→              <span>{report.createdAt}</span>
   299→            </span>
   300→            {allAnomalies.length > 0 && (
   301→              <span className="px-2 py-0.5 rounded-full text-[11px] font-bold bg-amber-500/20 text-amber-300 border border-amber-500/30 flex items-center space-x-1 animate-pulse">
   302→                <Zap className="w-3 h-3 text-amber-400" />
   303→                <span>监测到 {allAnomalies.length} 项数据异常波动</span>
   304→              </span>
   305→            )}
   306→          </div>
   307→          <h2 className="text-xl md:text-2xl font-extrabold tracking-tight">
   308→            {report.title}
   309→          </h2>
   310→        </div>

