async () => {
  const auth = JSON.parse(localStorage.getItem('auth-store') || '{}');
  const token = auth?.state?.token || auth?.token;
  const resp = await fetch('/api/report/export-pdf', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: JSON.stringify({ title: '导出探测', summary: 's', createdAt: '2026-08-21', templateType: 'x', kpiList: [], insights: [], charts: [], orientation: 'portrait' })
  });
  const buf = await resp.arrayBuffer();
  const bytes = new Uint8Array(buf.slice(0, 8));
  const magic = Array.from(bytes).map(b => String.fromCharCode(b)).join('');
  return {
    status: resp.status,
    contentType: resp.headers.get('content-type'),
    contentDisposition: resp.headers.get('content-disposition'),
    contentLength: resp.headers.get('content-length'),
    actualBytes: buf.byteLength,
    magic
  };
}
